        'organizational-leadership' => ['en' => 'Organizational Leadership', 'ar' => 'التميز في القيادة المؤسسية', 'days' => 3, 'summary' => ['en' => 'The success of any organization is deeply influenced by its leadership.', 'ar' => 'يتأثر نجاح أي مؤسسة تأثراً عميقاً بقيادتها.']],
