        'training-and-development-management' => ['en' => 'Training and Development Management', 'ar' => 'إدارة أقسام التدريب والتطوير', 'days' => 3, 'summary' => ['en' => 'Training and development professionals face ongoing pressure to deliver outstanding training services.', 'ar' => 'يواجه متخصصو التدريب والتطوير ضغوطاً مستمرة لتقديم خدمات تدريبية متميزة.']],
