        'strategic-sourcing-techniques-for-better-procurement-value' => ['en' => 'Strategic Sourcing: Techniques for Better Procurement Value', 'ar' => 'تقنيات واستراتيجية التوريد لتحقيق أفضل قيمة لعمليات المشتريات', 'days' => 3, 'summary' => ['en' => 'Procurement is often treated as an administrative function, with sourcing decisions made at a distance.', 'ar' => 'غالباً ما يُعامَل الشراء بوصفه وظيفة إدارية، إذ تُتخذ قرارات التوريد بمعزل عن السياق.']],
        'managing-supply-and-demand' => ['en' => 'Managing Supply and Demand', 'ar' => 'إدارة عمليات العرض والطلب', 'days' => 3, 'summary' => ['en' => 'This course leverages Cesim’s ‘SimFirm’ simulation tool to replicate real-world competitive and operational decision-making scenarios faced by managers.', 'ar' => 'تعتمد هذه الدورة على أداة المحاكاة \'SimFirm\' من Cesim لمحاكاة سيناريوهات اتخاذ القرارات التنافسية والتشغيلية الواقعية التي يواجهها المديرون.']],
